import { ChatTags, CustomTextStyling, EntityId, PlayerId, PNull, Pos, TranslatedText, RecursiveReadonly, BlockName } from "@bloxd"
import { BaseTeamInfo, BaseMapInfo, SessionBasedGameSetupOptions } from "./types"
import { SessionBasedPlayer } from "./SessionBasedPlayer"
import { SessionBasedGame } from "./SessionBasedGame"
import { roundOutwardsToChunkBoundary, getDimensions, preloadRect, style } from "./helpers"

let game: PNull<SessionBasedGame<any, any, SessionBasedPlayer<any, any>>> = null

onPlayerJoin = (playerId: PlayerId) => {
	game?.onPlayerJoin(playerId)
}

onPlayerLeave = (playerId: PlayerId) => {
	game?.onPlayerLeave(playerId)
}

tick = () => {
	game?.tick()
}

onPlayerChat = (playerId: PlayerId, message: string) => {
	return game?.onPlayerChat(playerId, message)
}

onMobKilledPlayer = (mobId: EntityId, playerId: PlayerId) => {
	game?.onPlayerDie(playerId)
}

onPlayerKilledOtherPlayer = (killerId: PlayerId, victimId: PlayerId) => {
	game?.onPlayerDie(victimId)
}

onRespawnRequest = (playerId: PlayerId) => {
	return game?.getPlayer(playerId)?.onRespawnRequest()
}

onPlayerBoughtShopItem = (playerId: PlayerId, categoryKey: string, itemKey: string) => {
	game?.onPlayerBoughtShopItem(playerId, categoryKey, itemKey)
}

onBlockStandStart = (playerId: PlayerId, x: number, y: number, z: number, blockName: BlockName) => {
	game?.onBlockStandStart(playerId, x, y, z, blockName)
}

/**
 * Create a new SessionBasedGame.
 * @param opts - The options for the game.
 * @param opts.teams - The teams for the game. This should include the team name, max players for this team, and hex colour.
 * @param opts.maps - The maps for the game. This should include the map name, source rectangle, and the spawn positions for each team.
 * @param opts.lobby - The lobby area. This should include the source rectangle, spawn info, and team pads for team choosing.
 * @param opts.playAreaRect - The play area rectangle. These will be rounded outwards to the nearest chunk boundary
 * @param opts.maxSpectators - The maximum number of spectators allowed in the game.
 * @param opts.emptyLobbyStartInSecs - The number of seconds to wait for the game to start when the lobby isn't full yet.
 * @param opts.fullLobbyStartInSecs - The number of seconds to wait for the game to start when the lobby is full.
 * @param opts.gameResetInSecs - The number of seconds to wait before resetting the game after the game finishes.
 * @param opts.mapVotingEnabled - Whether to enable map voting.
 * @param opts.onStart - The function to call when the game starts.
 * @param opts.onFinish - The function to call when the game finishes.
 * @param opts.getRightInfoText - The function to call to get the RightInfoText for the game.
 * @param opts.playerConstructor - The constructor for the player class. This should be a class that extends SessionBasedPlayer
 * @returns The game instance
 */
export function createGame<TeamInfo extends BaseTeamInfo, MapInfo extends BaseMapInfo<TeamInfo>, Player extends SessionBasedPlayer<TeamInfo, MapInfo>>(
	opts: SessionBasedGameSetupOptions<TeamInfo, MapInfo, Player>,
): SessionBasedGame<TeamInfo, MapInfo, Player> {
	if (game) {
		throw new Error("Game already setup")
	}
	if (opts.maps.length === 0) {
		throw new Error("No maps provided")
	}
	if (opts.teams.length < 2) {
		throw new Error(`At least 2 teams are required (got ${opts.teams.length})`)
	}
	for (const team of opts.teams) {
		if (team.maxPlayers < 1) {
			throw new Error(`Team ${team.name} max players must be at least 1`)
		}
	}
	opts.playAreaRect = roundOutwardsToChunkBoundary(opts.playAreaRect)
	const playAreaDimensions = getDimensions(opts.playAreaRect)
	preloadRect(opts.playAreaRect)

	const newMaps = []
	for (const map of opts.maps) {
		const newMap: MapInfo = {
			...map,
			source: {
				...map.source,
				rect: roundOutwardsToChunkBoundary(map.source.rect),
			},
		}
		const mapDimensions = getDimensions(newMap.source.rect)
		if (mapDimensions.l > playAreaDimensions.l || mapDimensions.w > playAreaDimensions.w || mapDimensions.h > playAreaDimensions.h) {
			throw new Error(`Map ${map.name} is too large for play area`)
		}

		// preload the map chunks
		preloadRect(newMap.source.rect)
		newMaps.push(newMap)
	}
	opts.maps = newMaps

	opts.lobby = {
		...opts.lobby,
		source: {
			...opts.lobby.source,
			rect: roundOutwardsToChunkBoundary(opts.lobby.source.rect),
		},
	}
	const lobbyDimensions = getDimensions(opts.lobby.source.rect)
	if (lobbyDimensions.l > playAreaDimensions.l || lobbyDimensions.w > playAreaDimensions.w || lobbyDimensions.h > playAreaDimensions.h) {
		throw new Error(`Lobby is too large for play area`)
	}
	preloadRect(opts.lobby.source.rect)

	const newGame = new SessionBasedGame<TeamInfo, MapInfo, Player>({
		...defaultSessionBasedGameSetupOptions,
		...opts,
	} as Required<SessionBasedGameSetupOptions<TeamInfo, MapInfo, Player>>)
	game = newGame
	return newGame
}

const defaultSessionBasedGameSetupOptions: Required<
	Omit<
		SessionBasedGameSetupOptions<BaseTeamInfo, BaseMapInfo<BaseTeamInfo>, SessionBasedPlayer<BaseTeamInfo, BaseMapInfo<BaseTeamInfo>>>,
		"teams" | "maps" | "playAreaRect" | "lobby"
	>
> = {
	maxSpectators: 10,
	emptyLobbyStartInSecs: 60,
	fullLobbyStartInSecs: 10,
	gameResetInSecs: 10,
	mapVotingEnabled: false,
	onStart: () => {
		api.broadcastMessage(style("Game started", game?.messageColours.success))
	},
	onFinish: (winningTeam: BaseTeamInfo) => {
		api.broadcastMessage(style(`${winningTeam.name} won the game`, winningTeam.colour))
	},
	getRightInfoText: (player: SessionBasedPlayer<BaseTeamInfo, BaseMapInfo<BaseTeamInfo>>) => {
		return game?.getStartingInText()
	},
	playerConstructor: SessionBasedPlayer,
}

export { SessionBasedGame, SessionBasedPlayer, BaseTeamInfo, BaseMapInfo, SessionBasedGameSetupOptions }
